const TEXT_TO_TYPE = "将人工智能技术融入视觉设计 / 品牌体验 / 创意生产";

export const Hero: React.FC = () => {
  const [displayText, setDisplayText] = useState('');
  const [isDeleting, setIsDeleting] = useState(false);
  const [loopNum, setLoopNum] = useState(0);
  const typingSpeed = 100;
  const deletingSpeed = 50;
  const pauseTime = 2000;

  useEffect(() => {
    let timer: any;
    const handleType = () => {
      const i = loopNum % 1; // Only one string in this case, but extendable
      const fullText = TEXT_TO_TYPE;

      setDisplayText(isDeleting 
        ? fullText.substring(0, displayText.length - 1) 
        : fullText.substring(0, displayText.length + 1)
      );

      if (!isDeleting && displayText === fullText) {
        timer = setTimeout(() => setIsDeleting(true), pauseTime);
      } else if (isDeleting && displayText === '') {
        setIsDeleting(false);
        setLoopNum(loopNum + 1);
      } else {
        timer = setTimeout(handleType, isDeleting ? deletingSpeed : typingSpeed);
      }
    };

    timer = setTimeout(handleType, typingSpeed);
    return () => clearTimeout(timer);
  }, [displayText, isDeleting, loopNum]);

  return (
    <section id="hero" className="min-h-screen flex flex-col md:flex-row items-center justify-center px-6 max-w-7xl mx-auto pt-20">

      {/* Content Side */}
